# exec'd from build.py. Data: data/habit-report-sample.json (generated by tapelog-mcp weekly_habit_report on SAMPLE data)
HR=json.load(open(f"{OUT}/data/habit-report-sample.json")); SUB="https://thetapelog.beehiiv.com/subscribe"
def _li(items,empty): return "<ul>"+("".join(f"<li>{html.escape(i['summary'])}</li>" for i in items) or f"<li>{empty}</li>")+"</ul>"
_tw=HR["this_week"]
_rows="".join(f"<tr><td>{html.escape(w)}</td><td>{c['trades']}</td><td>{c['size_up_after_loss']}</td><td>{c['losers_held_longer']}</td><td>{c['overtrading_burst']}</td><td>{c['time_of_day_slump']}</td></tr>"
 for w,c in list(HR["prior_weeks"].items())+[(HR["week_of"]+" (this week)",_tw)])
HRQ=[("What is the TapeLog weekly habit report?","A once-a-week summary of your own trading behavior. It compares this week with your prior weeks and lists which habits showed up more often and which faded, with counts: sizing up after a loss, holding losing trades longer than winners, overtrading bursts, and a time-of-day slump."),
("Does the habit report tell me what to trade?","No. It only counts things you already did. It never recommends buying, selling or holding any security and gives no picks, price targets, signals or predictions. It is educational and record-keeping software, not investment advice."),
("How do I get my own report?","Run the free TapeLog AI Coach (an open-source MCP server) in Claude, Cursor or another MCP client, import your DAS Trader or Robinhood CSVs, and ask for your weekly habit report. Subscribe to the newsletter for the weekly reminder and new report features.")]
body=f"""<h1>The TapeLog weekly habit report</h1>
<p>Every week, the TapeLog AI Coach compares your trades with your own prior weeks and counts the habits that appeared and the ones that faded. It covers sizing up after a loss, holding losers longer than winners, overtrading bursts and a time-of-day slump. It only describes what you did.</p>
<p><a class="btn" href="{SUB}">Get the weekly habit report</a><a class="btn alt" href="/tapelog/ai-coach/">Run it with the free AI Coach</a></p>
<p class="note"><strong>Sample data.</strong> The report below is built from a fictional, synthetic trade log: one sample DAS Trader day for this week plus three synthetic earlier weeks. It is not a real trader. <strong>Educational, not investment advice.</strong></p>
<h2>Sample report: week of {HR['week_of']}</h2>
<p>This week: {_tw['trades']} closed trades, net ${_tw['net_pnl']:,.2f}, compared with {HR['prior_weeks_compared']} prior weeks.</p>
<h3>Habits that appeared</h3>{_li(HR['appeared'],'None this week.')}
<h3>Habits that faded</h3>{_li(HR['faded'],'None this week.')}
<h3>Week by week</h3><table><tr><th>Week of</th><th>Trades</th><th>Size-up after loss</th><th>Losers held longer</th><th>Overtrading bursts</th><th>Time-of-day slump</th></tr>{_rows}</table>
<p class="small">How each count works: size-up = the next trade after a same-day loss was over 1.2x your usual position size; losers held longer = a losing trade held longer than your average winner; overtrading burst = 3 or more trades opened within 15 minutes; time-of-day slump = losing trades in your weakest entry window that week. {html.escape(HR['framing'])}</p>
<p class="note"><strong>Educational, not investment advice.</strong> {html.escape(HR['disclaimer'])}</p>
<h2>Get yours every week</h2><p>Subscribe to the free TapeLog newsletter for the weekly habit report reminder, sample breakdowns and new coach features. Then run the report on your own trades with the <a href="/tapelog/ai-coach/">TapeLog AI Coach</a> (ask: "Give me my weekly habit report").</p>
<p><a class="btn" href="{SUB}">Get the weekly habit report</a></p>
{AGENT_API_HTML}
<h2>FAQ</h2>{faq_html(HRQ)}"""
page("/habit-report/","TapeLog Weekly Habit Report: What Changed in Your Trading This Week (Sample)",
 "A free weekly report of your own trading habits: size-up after losses, losers held longer, overtrading bursts and time-of-day slumps, this week vs prior weeks. Sample data. Educational, not investment advice.",
 body,[faq_ld(HRQ)])
